`timescale 1ns/1ps
`ifndef CANNY_TEST_WIDTH
 `define CANNY_TEST_WIDTH 96
`endif
`ifndef CANNY_TEST_HEIGHT
 `define CANNY_TEST_HEIGHT 64
`endif
`ifndef CANNY_TEST_FRAMES
 `define CANNY_TEST_FRAMES 48
`endif
`ifndef CANNY_TEST_GAUSSIAN
 `define CANNY_TEST_GAUSSIAN 1
`endif
`ifndef CANNY_TEST_ADAPTIVE
 `define CANNY_TEST_ADAPTIVE 0
`endif
`ifndef CANNY_TEST_TAIL_SHIFT
 `define CANNY_TEST_TAIL_SHIFT 2
`endif
// Independent spatial arrays are generated by tools/canny_reference.py.
// Full coordinate sequences, per-cycle delay, exact NMS and final edges are checked.
module tb_canny_pixels;
 localparam W=`CANNY_TEST_WIDTH,H=`CANNY_TEST_HEIGHT,F=`CANNY_TEST_FRAMES,P=W*H;
 reg clk=0; always #5 clk=~clk;
 reg rst_n=0,fs=0,de=0;
 reg [10:0] x=0; reg [9:0] y=0; reg [15:0] rgb=0;
 integer cycle=0,frame=-1,ncount=0,ecount=0,total_n=0,total_e=0;
 wire edge_out,valid_out; wire [10:0] xo; wire [9:0] yo;
 wire [11:0] working_low,working_high;
 generate if(`CANNY_TEST_ADAPTIVE) begin:g_adaptive
  canny_adaptive_thresholds #(.WIDTH(W),.HEIGHT(H),.PERCENTILE_TAIL_SHIFT(`CANNY_TEST_TAIL_SHIFT)) controller(
   .clk(clk),.rst_n(rst_n),.frame_start(fs),.input_de(de),.input_x(x),.input_y(y),
   .gray_valid(dut.gv),.gray(dut.gray),.nms_valid(dut.nv),.nms_x(dut.nx),.nms_y(dut.ny),.nms_mag(dut.nmag),
   .source_id(frame),.source_ok_i(1'b1),.freeze_i(1'b0),.capture_lock_i(1'b0),
   .manual_low(12'd40),.manual_high(12'd80),.mode_request(1'b1),
   .low_o(working_low),.high_o(working_high));
 end else begin:g_fixed
  assign working_low=40;assign working_high=80;
 end endgenerate
 canny_stream #(.WIDTH(W),.GAUSSIAN(`CANNY_TEST_GAUSSIAN)) dut(
 .clk(clk),.rst_n(rst_n),.frame_start(fs),.low_i(working_low),.high_i(working_high),
 .de_i(de),.x_i(x),.y_i(y),.rgb565_i(rgb),.edge_o(edge_out),.valid_o(valid_out),.x_o(xo),.y_o(yo));
 reg [15:0] inputs[0:P*F-1];
 reg [11:0] expected_nms[0:P*F-1];
 integer input_clock[0:P-1];
 integer xi,yi,fi,fd_edges,fd_th,fd_stats,expected_x,expected_y;
 integer frame_lo=-1,frame_hi=-1;
 reg [2047:0] input_path,nms_path,edges_path,threshold_path,statistics_path;
 reg checking=0;
 always @(posedge clk) begin
  cycle=cycle+1;
  if(de) input_clock[y*W+x]=cycle;
  #1;
  if(checking && rst_n) begin
   if(dut.nv) begin
    expected_x=3+ncount%(W-6);expected_y=3+ncount/(W-6);
    if(dut.nx!==expected_x || dut.ny!==expected_y)
      $fatal(1,"NMS coordinate/valid frame=%0d idx=%0d got=%0d,%0d expected=%0d,%0d",frame,ncount,dut.nx,dut.ny,expected_x,expected_y);
    if(dut.nmag!==expected_nms[frame*P+dut.ny*W+dut.nx])
      $fatal(1,"NMS pixel frame=%0d x=%0d y=%0d rtl=%0d oracle=%0d",frame,dut.nx,dut.ny,dut.nmag,expected_nms[frame*P+dut.ny*W+dut.nx]);
    if(cycle!=input_clock[(dut.ny+3)*W+dut.nx+3]+9)
      $fatal(1,"NMS cycle alignment mismatch frame=%0d cycle=%0d",frame,cycle);
    if(ncount==0) begin
      frame_lo=dut.u_threshold.th_lo;frame_hi=dut.u_threshold.th_hi;
      $fdisplay(fd_th,"%0d %0d %0d",frame,frame_lo,frame_hi);
    end else if(frame_lo!=dut.u_threshold.th_lo || frame_hi!=dut.u_threshold.th_hi)
      $fatal(1,"Threshold changed inside valid NMS frame %0d",frame);
    ncount=ncount+1;total_n=total_n+1;
   end
   if(valid_out) begin
    expected_x=4+ecount%(W-8);expected_y=4+ecount/(W-8);
    if(xo!==expected_x || yo!==expected_y)
      $fatal(1,"Final coordinate/valid frame=%0d idx=%0d got=%0d,%0d expected=%0d,%0d",frame,ecount,xo,yo,expected_x,expected_y);
    if(cycle!=input_clock[(yo+4)*W+xo+4]+13)
      $fatal(1,"Final cycle alignment mismatch frame=%0d cycle=%0d source=%0d",frame,cycle,input_clock[(yo+4)*W+xo+4]);
    if(edge_out!==0 && edge_out!==1) $fatal(1,"Unknown output edge");
    $fdisplay(fd_edges,"%0d",edge_out);
    ecount=ecount+1;total_e=total_e+1;
   end
  end
 end
 initial begin
  if(!$value$plusargs("input=%s",input_path) || !$value$plusargs("nms=%s",nms_path)
   || !$value$plusargs("edges=%s",edges_path) || !$value$plusargs("thresholds=%s",threshold_path)
   || !$value$plusargs("statistics=%s",statistics_path))
   $fatal(1,"Required input/nms/edges/thresholds plusargs missing");
  $readmemh(input_path,inputs);$readmemh(nms_path,expected_nms);
  fd_edges=$fopen(edges_path,"w");fd_th=$fopen(threshold_path,"w");
  fd_stats=$fopen(statistics_path,"w");
  if(!fd_edges || !fd_th) $fatal(1,"Cannot create output records");
  repeat(4) @(negedge clk);rst_n=1;
  for(fi=0;fi<F;fi=fi+1) begin
   `ifdef CANNY_TEST_RECOVERY
    if(fi==2) begin
     // Abort a partial frame with a DE interruption. A reset explicitly
     // invalidates all history before a complete black recovery frame.
     checking=0;fs=1;@(negedge clk);fs=0;
     for(yi=0;yi<10;yi=yi+1)begin
      for(xi=0;xi<W;xi=xi+1)begin
       if(xi==W/2)begin de=0;repeat(3)@(negedge clk);end
       de=1;x=xi;y=yi;rgb=16'hffff;@(negedge clk);
      end
      de=0;repeat(16)@(negedge clk);
     end
     de=0;
     `ifndef CANNY_TEST_NO_RESET
      rst_n=0;repeat(4)@(negedge clk);rst_n=1;
     `else
      // Recovery must rely on the legal source-domain frame_start alone.
      repeat(32)@(negedge clk);
     `endif
    end
   `endif
   @(negedge clk);frame=fi;ncount=0;ecount=0;frame_lo=-1;frame_hi=-1;fs=1;checking=0;
   @(negedge clk);fs=0;
   repeat(32) @(negedge clk);checking=1;
   for(yi=0;yi<H;yi=yi+1) begin
    for(xi=0;xi<W;xi=xi+1) begin
     de=1;x=xi;y=yi;rgb=inputs[fi*P+yi*W+xi];@(negedge clk);
    end
    de=0;rgb=16'hdead;repeat(16) @(negedge clk);
   end
   de=0;repeat(128) @(negedge clk);
   if(ncount!=(W-6)*(H-6) || ecount!=(W-8)*(H-8))
    $fatal(1,"Frame valid count mismatch frame=%0d nms=%0d edges=%0d",frame,ncount,ecount);
   $display("FRAME %0d pixels=%0d high=%0d low=%0d",frame,ecount,frame_hi,frame_lo);
   `ifdef CANNY_TEST_STATS
    $fdisplay(fd_stats,"%0d %0d %0d %0d %0d %0d %0d",frame,g_adaptive.controller.candidate_high_o,
     g_adaptive.controller.sample_count_o,g_adaptive.controller.valid_count_o,
     g_adaptive.controller.gray_sum,g_adaptive.controller.pending_valid_o,g_adaptive.controller.fast_left);
   `endif
  end
  checking=0;$fclose(fd_edges);$fclose(fd_th);$fclose(fd_stats);
  $display("PASS: Canny pixel oracle coordinates cycles NMS frames=%0d nms=%0d final=%0d",F,total_n,total_e);
  $finish;
 end
 initial begin #2000000000;$fatal(1,"Timeout");end
endmodule
